handlers.onChange:
{event => {
                    const replacement = event.target.files?.[0];
                    if (!replacement) return;
                    setFiles(previous => previous.map((file, i) => i === index ? replacement : file));
                    update(index, { file: replacement, preview: null, error: '', committed: null });
                  }}

handlers.onClick:
{() =>
                onFiltersChange
                  ? onFiltersChange({ ...emptyFilters })
                  : setFilters({
                      type: "",
                      category: "",
                      milestone: "",
                      assignee: "",
                    })
              }

handlers.onDragOver:
{(e) => {
                  if (!canMove(issues.find(issue => issue.id === dragged)) || status.terminal) return;
                  e.preventDefault();
                  e.dataTransfer.dropEffect = "move";
                  setDropTarget(status.id);
                }}

handlers.onDrop:
{(e) => {
                  e.preventDefault();
                  if (!canTriage || status.terminal) return;
                  const id = e.dataTransfer.getData("text/plain");
                  if (issues.some((i) => i.id === id)) moveIssue(id, status.id);
                }}

handlers.onDragStart:
{(e) => {
                          if (!canMove(issue)) { e.preventDefault(); return; }
                          e.dataTransfer.setData("text/plain", issue.id);
                          e.dataTransfer.effectAllowed = "move";
                          setDragged(issue.id);
                        }}

